// Feature: 13-the-seal (U1.2, U1.3, U1.4, U2.1, U2.2, U3.1, U3.2, U8.2, U10.2 to U10.8)
//
// Property tests for the seal relief (design.md "Correctness Properties" 1, 2,
// 3, 12, 13 and 14). Each property runs over random 64-digit fingerprints
// generated by fast-check. Examples are in relief.test.ts.

import * as fc from "fast-check";
import { describe, expect, it } from "vitest";

import { WAX_PATH } from "./seal-art";
import {
  BLANK_RELIEF,
  COARSE_FEATURE_MAX,
  COARSE_MAX_RADIUS,
  DOT_COUNT,
  NOTCH_MAX,
  NOTCH_MIN,
  RELIEF_MAX_RADIUS,
  RING_MAX,
  RING_MIN,
  RING_WIDTH,
  TICK_COUNT,
  isFingerprintHex,
  reliefDistance,
  movedMarks,
  sealRelief,
  type CoarseNotch,
  type Pt,
  type ReliefMark,
  type SealRelief,
} from "./relief";

const HEX = "0123456789abcdef";
const RUNS = 60;

/** A random 64-character lowercase hex fingerprint. */
const hash64 = fc
  .array(fc.integer({ min: 0, max: 15 }), { minLength: 64, maxLength: 64 })
  .map((digits) => digits.map((n) => HEX[n]).join(""));

function withDigit(h: string, p: number, c: string): string {
  return h.slice(0, p) + c + h.slice(p + 1);
}

function relief(h: string): Extract<SealRelief, { kind: "relief" }> {
  const r = sealRelief(h);
  if (r.kind !== "relief") throw new Error("expected a relief");
  return r;
}

function dist(p: Pt, q: Pt): number {
  return Math.sqrt((p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2);
}

/** Largest move of any corner, index-matched, of two notches. */
function notchMove(a: CoarseNotch, b: CoarseNotch): number {
  let max = 0;
  for (let i = 0; i < 4; i++)
    max = Math.max(max, dist(a.corners[i], b.corners[i]));
  return max;
}

/** Which fine mark indices differ between two reliefs (0 to 63). */
function changedMarkIndices(a: SealRelief, b: SealRelief): number[] {
  if (a.kind !== "relief" || b.kind !== "relief") return [];
  const out: number[] = [];
  for (let i = 0; i < a.marks.length; i++) {
    if (JSON.stringify(a.marks[i]) !== JSON.stringify(b.marks[i])) out.push(i);
  }
  return out;
}

/** The mark index of fine digit p (8 to 63): tick p/2 for even p, dot (p-1)/2 for odd p. */
function markIndexOfDigit(p: number): number {
  return p % 2 === 0 ? p / 2 : TICK_COUNT + (p - 1) / 2;
}

/** Points on the wax outline, sampled along each cubic segment of WAX_PATH. */
function waxOutlinePoints(): Pt[] {
  const segments = WAX_PATH.match(/[MCZ][^MCZ]*/g) ?? [];
  const points: Pt[] = [];
  let cur: Pt = [0, 0];
  for (const seg of segments) {
    const cmd = seg[0];
    const nums = seg
      .slice(1)
      .trim()
      .split(/\s+/)
      .filter((s) => s.length > 0)
      .map(Number);
    if (cmd === "M") {
      cur = [nums[0], nums[1]];
      points.push(cur);
    } else if (cmd === "C") {
      for (let i = 0; i + 5 < nums.length; i += 6) {
        const p1: Pt = [nums[i], nums[i + 1]];
        const p2: Pt = [nums[i + 2], nums[i + 3]];
        const p3: Pt = [nums[i + 4], nums[i + 5]];
        for (let s = 1; s <= 200; s++) {
          const t = s / 200;
          const u = 1 - t;
          const x =
            u * u * u * cur[0] +
            3 * u * u * t * p1[0] +
            3 * u * t * t * p2[0] +
            t * t * t * p3[0];
          const y =
            u * u * u * cur[1] +
            3 * u * u * t * p1[1] +
            3 * u * t * t * p2[1] +
            t * t * t * p3[1];
          points.push([x, y]);
        }
        cur = p3;
      }
    }
  }
  return points;
}

describe("Property 1: relief is deterministic and total", () => {
  it("the same fingerprint gives deeply equal reliefs and identical strings", () => {
    fc.assert(
      fc.property(hash64, (h) => {
        const a = sealRelief(h);
        const b = sealRelief(h);
        expect(a).toEqual(b);
        if (a.kind !== "relief" || b.kind !== "relief")
          throw new Error("expected relief");
        expect(a.tickPath).toBe(b.tickPath);
        expect(a.dotPath).toBe(b.dotPath);
        expect(a.coarse?.notchPath).toBe(b.coarse?.notchPath);
        expect(a.coarse?.signature).toBe(b.coarse?.signature);
      }),
      { numRuns: RUNS },
    );
  });

  it("any input that is not exactly 64 lowercase hex characters gives BLANK_RELIEF and does not throw", () => {
    const notHash = fc.oneof(
      fc.string(),
      fc.integer(),
      fc.constant(undefined),
      fc.constant(null),
      hash64.map((h) => h.slice(0, 63)),
      hash64.map((h) => `${h}0`),
      hash64.map((h) => h.toUpperCase()),
      hash64.map((h) => `${h.slice(0, 63)}g`),
    );
    fc.assert(
      fc.property(notHash, (value) => {
        fc.pre(!isFingerprintHex(value));
        expect(sealRelief(value)).toEqual(BLANK_RELIEF);
      }),
      { numRuns: RUNS },
    );
  });
});

describe("Property 2: a one-digit change moves a feature, on all 64 digits", () => {
  it("any single hex digit change moves a feature, and the right feature for its position", () => {
    fc.assert(
      fc.property(
        hash64,
        fc.integer({ min: 0, max: 63 }),
        fc.integer({ min: 0, max: 15 }),
        (h, p, c) => {
          fc.pre(HEX[c] !== h[p]);
          const h2 = withDigit(h, p, HEX[c]);
          const a = relief(h);
          const b = relief(h2);

          expect(reliefDistance(a, b)).toBeGreaterThanOrEqual(1 - 1e-9);
          const changed =
            a.tickPath !== b.tickPath ||
            a.dotPath !== b.dotPath ||
            a.coarse.notchPath !== b.coarse.notchPath ||
            a.coarse.signature !== b.coarse.signature;
          expect(changed).toBe(true);

          if (p <= 7) {
            // Notch 0 sits at the rotation slot, so any digit change in 0 to 7 moves it (at least 3 units).
            expect(
              notchMove(a.coarse.notches[0], b.coarse.notches[0]),
            ).toBeGreaterThanOrEqual(3);
          } else {
            expect(movedMarks(a, b, 1 - 1e-9)).toBeGreaterThanOrEqual(1);
          }
        },
      ),
      { numRuns: 400 },
    );
  });
});

describe("Property 3: relief stays inside the wax and keeps its fixed kind", () => {
  it("has 32 ticks, 32 dots, all fine vertices inside 43.5, no <text>, <image> or <use>", () => {
    fc.assert(
      fc.property(hash64, (h) => {
        const r = relief(h);
        const ticks = r.marks.filter((m) => m.kind === "tick");
        const dots = r.marks.filter((m) => m.kind === "dot");
        expect(r.marks).toHaveLength(TICK_COUNT + DOT_COUNT);
        expect(ticks).toHaveLength(TICK_COUNT);
        expect(dots).toHaveLength(DOT_COUNT);

        for (const m of r.marks as readonly ReliefMark[]) {
          if (m.kind === "tick") {
            for (const corner of m.corners) {
              expect(dist(corner, [50, 50])).toBeLessThanOrEqual(
                RELIEF_MAX_RADIUS,
              );
            }
          } else {
            expect(dist([m.cx, m.cy], [50, 50]) + m.r).toBeLessThanOrEqual(
              RELIEF_MAX_RADIUS,
            );
          }
        }

        // Neighbouring ticks have a positive gap: no corner of one meets a corner of the next.
        for (let k = 0; k < TICK_COUNT; k++) {
          const a = ticks[k];
          const b = ticks[(k + 1) % TICK_COUNT];
          if (a.kind !== "tick" || b.kind !== "tick")
            throw new Error("expected tick");
          let min = Infinity;
          for (const p of a.corners)
            for (const q of b.corners) min = Math.min(min, dist(p, q));
          expect(min).toBeGreaterThan(0);
        }

        const text = [r.tickPath, r.dotPath, r.coarse.notchPath].join(" ");
        expect(text).not.toMatch(/[<>]/);
      }),
      { numRuns: RUNS },
    );
  });
});

describe("Property 12: the Coarse_Layer keeps its fixed structure and ranges", () => {
  it("notch count, ring count, feature count, shapes, clearances and the wax edge", () => {
    const waxMin = Math.min(
      ...waxOutlinePoints().map((p) => dist(p, [50, 50])),
    );
    // Smallest centre-to-wax-edge distance, sampled from WAX_PATH: 45.7987 at 20,000
    // samples per segment (the design quotes about 45.80). The floor is set below that measurement.
    expect(waxMin).toBeGreaterThanOrEqual(45.79);
    expect(COARSE_MAX_RADIUS).toBeLessThan(waxMin);

    fc.assert(
      fc.property(hash64, (h) => {
        const { coarse } = relief(h);
        if (!coarse) throw new Error("expected coarse layer");
        const n = coarse.notches.length;
        const rings = coarse.rings.length;
        expect(n).toBeGreaterThanOrEqual(NOTCH_MIN);
        expect(n).toBeLessThanOrEqual(NOTCH_MAX);
        expect(rings).toBeGreaterThanOrEqual(RING_MIN);
        expect(rings).toBeLessThanOrEqual(RING_MAX);
        expect(n + rings).toBeLessThanOrEqual(COARSE_FEATURE_MAX);

        for (const notch of coarse.notches) {
          const [i0, i1, o1, o0] = notch.corners;
          expect(dist(i0, o0)).toBeCloseTo(5.9, 9); // radial side
          expect(dist(i0, i1)).toBeCloseTo(11.0, 9); // tangential side
          expect(dist(o1, o0)).toBeCloseTo(11.0, 9);
          for (const corner of notch.corners) {
            expect(dist(corner, [50, 50])).toBeLessThanOrEqual(
              COARSE_MAX_RADIUS,
            );
          }
        }

        for (let i = 0; i < n; i++) {
          for (let j = i + 1; j < n; j++) {
            let min = Infinity;
            for (const p of coarse.notches[i].corners) {
              for (const q of coarse.notches[j].corners)
                min = Math.min(min, dist(p, q));
            }
            expect(min).toBeGreaterThanOrEqual(10);
          }
        }

        // Ring clearances: each ring edge is at least 0.8 from any notch and from the other ring.
        const notchOuter = Math.max(
          ...coarse.notches.flatMap((x) =>
            x.corners.map((p) => dist(p, [50, 50])),
          ),
        );
        const ringEdges = coarse.rings.map((g) => ({
          inner: g.radius - RING_WIDTH / 2,
          outer: g.radius + RING_WIDTH / 2,
        }));
        for (const edge of ringEdges) {
          expect(edge.inner - notchOuter).toBeGreaterThanOrEqual(0.8 - 1e-9);
          expect(edge.outer).toBeLessThanOrEqual(COARSE_MAX_RADIUS + 1e-9);
        }
        if (ringEdges.length === 2) {
          const [a, b] = ringEdges;
          expect(Math.abs(b.inner - a.outer)).toBeGreaterThanOrEqual(
            0.8 - 1e-9,
          );
        }

        // The smallest side of any coarse feature is at least 4.2 units.
        expect(RING_WIDTH).toBeGreaterThanOrEqual(4.2 - 1e-9);
      }),
      { numRuns: RUNS },
    );
  });
});

describe("Property 13: the two layers read disjoint digits", () => {
  it("changing a coarse digit leaves the fine layer unchanged, and changing a fine digit leaves the coarse layer unchanged", () => {
    fc.assert(
      fc.property(
        hash64,
        fc.integer({ min: 0, max: 63 }),
        fc.integer({ min: 0, max: 15 }),
        (h, p, c) => {
          fc.pre(HEX[c] !== h[p]);
          const a = relief(h);
          const b = relief(withDigit(h, p, HEX[c]));
          if (p <= 7) {
            expect(b.marks).toEqual(a.marks);
            expect(b.tickPath).toBe(a.tickPath);
            expect(b.dotPath).toBe(a.dotPath);
          } else {
            expect(b.coarse).toEqual(a.coarse);
            expect(b.coarse.notchPath).toBe(a.coarse.notchPath);
          }
        },
      ),
      { numRuns: 400 },
    );
  });

  it("ticks 0 to 3 and dots 0 to 3 are identical for every fingerprint", () => {
    fc.assert(
      fc.property(hash64, hash64, (h1, h2) => {
        const a = relief(h1);
        const b = relief(h2);
        for (let k = 0; k < 4; k++) {
          expect(b.marks[k]).toEqual(a.marks[k]);
          expect(b.marks[TICK_COUNT + k]).toEqual(a.marks[TICK_COUNT + k]);
        }
      }),
      { numRuns: RUNS },
    );
  });
});

describe("Property 14: coarse and fine mapping is one-to-one on the fine digits", () => {
  it("every fine digit has its own mark: changing position p alone moves exactly the mark for p", () => {
    const seen = new Set<number>();
    for (let p = 8; p <= 63; p++) {
      const idx = markIndexOfDigit(p);
      expect(seen.has(idx)).toBe(false);
      seen.add(idx);
    }
    expect(seen.size).toBe(56);

    fc.assert(
      fc.property(
        hash64,
        fc.integer({ min: 8, max: 63 }),
        fc.integer({ min: 0, max: 15 }),
        (h, p, c) => {
          fc.pre(HEX[c] !== h[p]);
          const a = relief(h);
          const b = relief(withDigit(h, p, HEX[c]));
          expect(changedMarkIndices(a, b)).toEqual([markIndexOfDigit(p)]);
        },
      ),
      { numRuns: 400 },
    );
  });
});
